CREATE TABLE users(id SERIAL PRIMARY KEY,email VARCHAR(320) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE organizations(id SERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE organization_members(organization_id INT REFERENCES organizations(id) ON DELETE CASCADE,user_id INT REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(organization_id,user_id));
CREATE TABLE projects(id SERIAL PRIMARY KEY,organization_id INT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,name VARCHAR(200) NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE retry_policies(id SERIAL PRIMARY KEY,strategy VARCHAR(30) NOT NULL DEFAULT 'exponential',max_retries INT NOT NULL DEFAULT 3,base_delay_seconds INT NOT NULL DEFAULT 5,max_delay_seconds INT NOT NULL DEFAULT 300);
CREATE TABLE queues(id SERIAL PRIMARY KEY,project_id INT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name VARCHAR(200) NOT NULL,priority INT NOT NULL DEFAULT 0,concurrency_limit INT NOT NULL DEFAULT 4,retry_policy_id INT REFERENCES retry_policies(id) ON DELETE SET NULL,is_paused BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(project_id,name));
CREATE TABLE jobs(id BIGSERIAL PRIMARY KEY,queue_id INT NOT NULL REFERENCES queues(id) ON DELETE CASCADE,job_type VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'queued',payload JSONB NOT NULL,priority INT NOT NULL DEFAULT 0,run_at TIMESTAMPTZ,cron_expr VARCHAR(120),batch_id VARCHAR(100),attempt_count INT NOT NULL DEFAULT 0,max_attempts INT NOT NULL DEFAULT 4,last_error TEXT,claimed_by VARCHAR(200),claimed_at TIMESTAMPTZ,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX ix_jobs_claim ON jobs(queue_id,status,priority,run_at,created_at);
CREATE TABLE scheduled_jobs(id SERIAL PRIMARY KEY,job_id BIGINT UNIQUE NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,cron_expr VARCHAR(120) NOT NULL,next_run_at TIMESTAMPTZ NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE workers(id VARCHAR(200) PRIMARY KEY,status VARCHAR(20) NOT NULL DEFAULT 'online',started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_heartbeat TIMESTAMPTZ NOT NULL DEFAULT NOW(),current_jobs INT NOT NULL DEFAULT 0,hostname VARCHAR(255));
CREATE TABLE worker_heartbeats(id BIGSERIAL PRIMARY KEY,worker_id VARCHAR(200) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE job_executions(id BIGSERIAL PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,worker_id VARCHAR(200) REFERENCES workers(id) ON DELETE SET NULL,attempt_number INT NOT NULL,status VARCHAR(20) NOT NULL,started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ,result JSONB,error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX ix_job_executions_job ON job_executions(job_id);
CREATE TABLE job_logs(id BIGSERIAL PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,level VARCHAR(20) NOT NULL DEFAULT 'INFO',message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE dead_letter_jobs(id BIGSERIAL PRIMARY KEY,job_id BIGINT UNIQUE NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,final_error TEXT,moved_at TIMESTAMPTZ NOT NULL DEFAULT NOW());